// intake.review.decide — E2 AC2/AC3, SOP-DEL-01 §8. Generated by `pnpm gen:command`; guard cases kept,
// acceptance cases added. The card is filled and submitted with the intake commands.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createFakeClock, createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  Forbidden,
  grantOf,
  NotFound,
  openTestKernel,
  RuleViolation,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { decideIntake } from '../commands/decide-intake.ts';
import { saveHandoverCard } from '../commands/save-handover-card.ts';
import { submitHandoverCard } from '../commands/submit-handover-card.ts';
import { itemCodes } from '../rules/handover-checklist.ts';

const sales = aStaffActor({ roles: ['sales'] });
const director = aStaffActor({ roles: ['director'] });
const clock = createFakeClock(new Date('2026-11-20T09:00:00Z')); // a Friday; +5 working days (GB) = 27 Nov
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;
const rows = (from: string, params: unknown[] = []) => countRows(testDb.url, from, params);

const items = itemCodes.map((code) =>
  code.startsWith('F') ? { code, status: 'provided' } : { code, status: 'provided', value: 'in the folder' },
);
async function submitCard() {
  const content = { identification: { projectName: 'Mall A counting', projectType: 'new' } };
  const input = { siteId: siteA, content, items, installsOrConfigures: true, newClientOrPlace: true };
  await t.kernel.execute(saveHandoverCard, sales, input, 'test');
  await t.kernel.execute(submitHandoverCard, sales, { siteId: siteA }, 'test');
}
const decide = (input: Record<string, unknown>) =>
  t.kernel.execute(
    decideIntake,
    director,
    { siteId: siteA, folderStandard: 'L', conditions: [], ...input },
    'test',
  );

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url, { clock: clock.now });
  t.grant(director, createClient.permission, createSite.permission, decideIntake.permission);
  t.grant(sales, saveHandoverCard.permission, submitHandoverCard.permission);
  const a = await t.kernel.execute(
    createClient,
    director,
    { shortCode: 'CLIENTA', name: 'Client A' },
    'test',
  );
  const place = { countryCode: 'GB', cityCode: 'LON', cityName: 'London', name: 'Mall A', standard: 'L' };
  ({ id: siteA } = await t.kernel.execute(createSite, director, { clientId: a.id, ...place }, 'test'));
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('intake.review.decide', () => {
  it('is for the Delivery Director only; needs a submitted card', async () => {
    expect(grantOf(decideIntake.permission)?.roles).toEqual(['director']);
    const asSales = t.kernel.execute(
      decideIntake,
      sales,
      { siteId: siteA, decision: 'accepted', folderStandard: 'L', conditions: [] },
      'test',
    );
    await expect(asSales).rejects.toBeInstanceOf(Forbidden);
    await expect(decide({ decision: 'accepted' })).rejects.toBeInstanceOf(NotFound);
    await expect(decide({ siteId: randomUUID(), decision: 'accepted' })).rejects.toBeInstanceOf(NotFound);
  });

  it('a return lists the gaps; Sales then resubmits as version 2', async () => {
    await submitCard();
    await expect(decide({ decision: 'returned' })).rejects.toBeInstanceOf(RuleViolation);
    const r = await decide({ decision: 'returned', reasons: 'C3 point design unusable' });
    expect([r.decision, r.version]).toEqual(['returned', 1]);
    expect(await rows(`handover_card WHERE site_id = $1 AND status = 'returned'`, [siteA])).toBe(1);
    expect(await rows(`outbox WHERE event_type = 'intake.review.decided'`)).toBe(1);
  });

  it('refuses a blocking item as a condition and a deadline after 5 working days, recording nothing', async () => {
    await submitCard();
    const blocking = decide({
      decision: 'accepted_with_conditions',
      conditions: [{ itemCode: 'A4', text: 'dates to follow', deadline: '2026-11-25' }],
    });
    await expect(blocking).rejects.toThrow(/SOP-DEL-01 §8.*A4 can never be a condition/);
    const late = decide({
      decision: 'accepted_with_conditions',
      conditions: [{ itemCode: 'B2', text: 'secondary contact', deadline: '2026-11-30' }],
    });
    await expect(late).rejects.toThrow(/2026-11-20 to 2026-11-27/);
    expect(await rows('intake_decision')).toBe(1);
  });

  it('accepts with a non-blocking condition: decision, condition and card status recorded', async () => {
    const r = await decide({
      decision: 'accepted_with_conditions',
      conditions: [{ itemCode: 'B2', text: 'secondary contact', deadline: '2026-11-27' }],
      assignedPmId: randomUUID(),
    });
    expect([r.version, r.latestDeadline]).toEqual([2, '2026-11-27']);
    expect(await rows(`intake_condition WHERE item_code = 'B2' AND status = 'open'`)).toBe(1);
    expect(
      await rows(`handover_card WHERE site_id = $1 AND status = 'accepted_with_conditions'`, [siteA]),
    ).toBe(1);
    expect(await rows('audit_event WHERE command = $1', [decideIntake.name])).toBe(2);
  });
});
